import { Component, OnDestroy, OnInit, ViewChild } from '@angular/core';
import { ActivatedRoute, NavigationEnd, Router } from '@angular/router';
import { IonContent } from '@ionic/angular';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
import { CurrentStore } from '@rsApp/modules/store/store.module';
import { AppSettings } from '@rsApp/modules/utils/providers/app-setting';
import { filter, Subject, takeUntil } from 'rxjs';

@Component({
  selector: 'deals-page',
  templateUrl: './deals-page.html',
  styleUrls: ['./deals-page.scss'],
})
export class DealsPageComponent implements OnInit, OnDestroy {
  @ViewChild(IonContent) content!: IonContent;
  public tabItems: Array<any> = [
    {
      id: 'rewards',
      label: 'myRewards',
    },
    {
      id: 'offers',
      label: 'myOffers',
    },
    {
      id: 'coupons',
      label: 'myCoupons',
    },
    {
      id: 'loaded-savings',
      label: 'myLoaded Savings',
    },
  ];
  public activeTab: string = '';
  public activeSlug: string = '';
  public settingsTabItems: Array<any> = [];
  private OFFER_PATH_SETTING = 'PROMOTIONS';
  public dealSupport: boolean = true;
  public isInit: boolean = true;
  public loaded: boolean;
  private _destroy$: Subject<boolean> = new Subject();

  constructor(
    public router: Router,
    public route: ActivatedRoute,
    public cStore: CurrentStore,
    public cre: Credential,
    public appSettings: AppSettings
  ) {
    const slug = this.route.snapshot.children[0].routeConfig.path || 'rewards';
    this.activeSlug = slug;
    this.router.events
      .pipe(
        filter((event) => event instanceof NavigationEnd),
        takeUntil(this._destroy$)
      )
      .subscribe(() => {
        if (this.isInit) {
          this.isInit = false;
        } else {
          const activeRoute = this.getDeepestChild(this.router.routerState.root);
          const configPath = activeRoute.routeConfig?.path;
          if (!configPath?.startsWith(':')) {
            this.activeSlug = configPath;
            this.setActiveTab();
          }
        }
      });
  }

  getDeepestChild(route: ActivatedRoute): ActivatedRoute {
    while (route.firstChild) {
      route = route.firstChild;
    }
    return route;
  }

  setActiveTab() {
    const currentTab = this.settingsTabItems.find(
      (s) => s.id.toLocaleLowerCase() === this.activeSlug.toLocaleLowerCase()
    );
    if (currentTab) this.activeTab = currentTab.id;

    setTimeout(() => (this.loaded = true));
  }

  async ngOnInit() {
    const rs = await this.appSettings.getSettingByPath(this.OFFER_PATH_SETTING).toPromise();
    const dealNagition = rs['deal_page_navigation_support'];
    this.dealSupport = rs['deals_support'];
    if (!rs) return;
    this.settingsTabItems = dealNagition || [];
    this.setActiveTab();
  }

  ionViewDidEnter() {
    window.addEventListener('scrollToTop', this.handleScrollToTop);
  }

  ionViewWillLeave() {
    window.removeEventListener('scrollToTop', this.handleScrollToTop);
  }

  private handleScrollToTop = () => {
    const scrollTopListId: string[] = ['#offers-list', '#coupons-list'];

    scrollTopListId.forEach((idElement: string) => {
      document.querySelector(idElement)?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    });
    this.content?.scrollToTop();
  };

  selectTab($event) {
    const data = $event.detail;
    this.activeTab = data.id;
    this.loaded = false;
    this.router.navigate([`/tabs/deals/${data.id}`], { relativeTo: this.route });
  }

  ngOnDestroy() {
    this._destroy$.next(true);
    this._destroy$.complete();
  }
}
