import { Inject, Injectable } from '@angular/core';
import { MagEComCoreApiHttpClient } from '@rsApp/modules/gateway/mag-ecom-core-api.service';
import { MAG_OFFER_V2_HTTP_CLIENT, MAG_REWARD_HTTP_CLIENT } from '../../utils/ecom-api-configs';
import { IMagCouponDetail, IMagDealDetail, IMagRewardDetail } from '../model/interface';
import { Observable } from 'rxjs';

@Injectable()
export class OfferService {
  constructor(
    @Inject(MAG_OFFER_V2_HTTP_CLIENT) private api: MagEComCoreApiHttpClient,
    @Inject(MAG_REWARD_HTTP_CLIENT) private apiReward: MagEComCoreApiHttpClient
  ) {}

  getOfferByCode(storeCode: string, offerCode: string, transactionId?: string): Observable<IMagDealDetail> {
    //customrcode is hardcoded , will remove it later
    return this.api.get(
      `/Offer/GetDealDetail?storeCode=${storeCode}&offerCode=${offerCode}${transactionId ? `&transactionId=${transactionId}` : ''}`
    ) as Observable<IMagDealDetail>;
  }

  getCouponByCode(couponCode: string): Observable<IMagCouponDetail> {
    return this.api.get(`/coupons/${couponCode}`) as Observable<IMagCouponDetail>;
  }

  getRewardDetail(
    offerCode: string,
    programCode: string,
    clippedRewardId: string = null
  ): Observable<IMagRewardDetail> {
    let url = `/${offerCode}/programs/${programCode}`;
    if (clippedRewardId) {
      url += `?clippedRewardId=${clippedRewardId}`;
    }
    return this.apiReward.get(url) as Observable<IMagRewardDetail>;
  }

  getRewardClippedList(): Observable<Array<any>> {
    const url = '/clipped';
    return this.apiReward.get(url) as Observable<Array<any>>;
  }

  getRewardClaimProduct(pi: number = 1, ps: number = 10): Observable<any> {
    const url = `/programs/free-products/class/claim-product?pi=${pi}&ps=${ps}`;
    return this.apiReward.get(url) as Observable<any>;
  }
}
