import { Component, OnDestroy, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { Storage } from '@ionic/storage';
import { TranslateService } from '@ngx-translate/core';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
import { CurrentStore } from '@rsApp/modules/store/store.module';
import { DEFAULT_LOCALE, LOCAL_LOCALE_KEY } from '@rsApp/modules/utils/constants/constants';
import { AppSettings } from '@rsApp/modules/utils/providers/app-setting';
import * as moment from 'moment';
import { firstValueFrom, Subject, takeUntil } from 'rxjs';
import { OfferProductService } from '../../providers/offer-product.service';
import { OfferService } from '../../providers/offer.service';

@Component({
  selector: 'reward-detail',
  templateUrl: './reward-detail.html',
  styleUrls: ['./reward-detail.scss'],
})
export class RewardDetailPageComponent implements OnInit, OnDestroy {
  private _destroy$: Subject<boolean> = new Subject();
  reward: any;
  offerCode: string;
  programCode: string;
  clippedRewardId: string;
  offerExpirationDate: string;
  startDate: string;
  endDate: string;

  conditionUpcs: any[];
  participatingProducts: any[];
  isBundle: boolean;
  isLoadedParticipatingProducts = false;
  store: any;

  returnRoute: string;
  isLoading: boolean = true;
  labelArr: { [key: string]: string };
  defaultProgramCode = 'free-products';

  constructor(
    public router: Router,
    public route: ActivatedRoute,
    public rewardService: OfferService,
    public offerProductService: OfferProductService,
    public cStore: CurrentStore,
    public cre: Credential,
    public appSettings: AppSettings,
    public translate: TranslateService,
    private storage: Storage
  ) {}

  ngOnInit() {
    this.route.paramMap.pipe(takeUntil(this._destroy$)).subscribe((params) => {
      this.offerCode = params.get('offerCode');
    });
    this.route.queryParamMap.pipe(takeUntil(this._destroy$)).subscribe((queryParams) => {
      this.programCode = queryParams.get('programCode');
      this.clippedRewardId = queryParams.get('clippedRewardId');
      this.returnRoute = queryParams.get('returnRoute');
    });
  }

  ngOnDestroy() {
    this._destroy$.next(true);
    this._destroy$.complete();
  }

  async ionViewWillEnter() {
    try {
      await this.init();
    } catch (error) {
      console.error(error);
    }
  }

  async init() {
    this.store = await this.cStore.getStore();
    if (!this.store) {
      console.error('Store not found');
      return;
    }

    const locale = this.translate.currentLang || (await this.storage.get(LOCAL_LOCALE_KEY)) || DEFAULT_LOCALE;
    const rs = await firstValueFrom(this.appSettings.getSettingByPath('LOYALTY'));
    const programLabel = rs[`${this.programCode.replace('-', '_')}_program_label_settings`];
    this.labelArr =
      programLabel &&
      programLabel.reduce((pre, curr) => ({ ...pre, [curr.SettingName]: curr.SettingValue[locale] }), {});

    this.reward = await this.fetchRewardData();
    if (!this.reward) {
      console.error('Reward not found');
      this.isLoading = false;
      return;
    }

    this.initRewardData();
    await this.initParticipatingData();
    this.isLoading = false;
  }

  initRewardData() {
    const { ExpirationDate, StartDate, EndDate } = this.reward || {};

    this.offerExpirationDate = ExpirationDate ? moment(ExpirationDate).format('MMM DD, YYYY') : '';
    this.startDate = StartDate ? moment(StartDate).format('MMM DD, YYYY') : '';
    this.endDate = EndDate ? moment(EndDate).format('MMM DD, YYYY') : '';
  }

  async initParticipatingData() {
    const { ProductUPCs, IsBundle } = this.reward || {};

    this.conditionUpcs = ProductUPCs?.length > 0 ? ProductUPCs.map((upc) => this.padLeadingZeros(upc, 14)) : [];

    if (this.conditionUpcs?.length > 0) {
      const dataSource = await this.fetchDataByUpcs(this.conditionUpcs);
      this.participatingProducts = dataSource?.length > 0 ? dataSource : null;
    }
    this.isBundle = IsBundle;
    this.isLoadedParticipatingProducts = true;
  }

  async processUpcGroups(upcGroups: string[][]) {
    try {
      const promises = upcGroups.map((group) => this.fetchDataByUpcs(group));
      const results = await Promise.all(promises);
      return results;
    } catch (error) {
      console.error('Error processing UPC groups:', error);
      return [];
    }
  }

  async fetchDataByUpcs(upcs: string[]) {
    return await firstValueFrom(
      this.offerProductService.getParticipatingProducts(upcs, this.store?.StoreCode, true, this.cre.currentUser)
    );
  }

  async fetchRewardData() {
    try {
      const data = await firstValueFrom(
        this.rewardService.getRewardDetail(this.offerCode, this.programCode, this.clippedRewardId)
      );
      if (!data) return null;
      return data;
    } catch (error) {
      console.error('Error fetching reward data:', error);
      return null;
    }
  }

  padLeadingZeros(num, size) {
    let s = num + '';
    while (s.length < size) s = '0' + s;
    return s;
  }
}
