import { Component, HostListener, OnDestroy, OnInit, ViewChild, NgZone } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { CurrentStore } from '@rsApp/modules/store/store.module';
import * as moment from 'moment';
import { firstValueFrom, Subject, Subscription, takeUntil } from 'rxjs';
import { EnumMagOfferType, IMagDealDetail, enumCouponDisplayType } from '../../model/interface';
import { OfferProductService } from '../../providers/offer-product.service';
import { OfferService } from '../../providers/offer.service';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
import { RouteTrackerService } from '@rsApp/modules/utils/providers/route-tracker.service';
import { EnumMagFulfillmentManagementRenderType } from '@rsApp/core/enum';
import { AppSettings } from '@rsApp/modules/utils/providers/app-setting';
import { IonContent } from '@ionic/angular';

@Component({
  selector: 'offer-detail',
  templateUrl: './offer-detail.html',
  styleUrls: ['./offer-detail.scss'],
})
export class OfferDetailPageComponent implements OnInit, OnDestroy {
  @ViewChild(IonContent) content!: IonContent;
  private _destroy$: Subject<boolean> = new Subject();
  offer: IMagDealDetail;
  magGallery: string;
  offerCode: string;
  transactionId: string;
  offerExpirationDate: string;
  startDate: string;
  endDate: string;
  isCoupon: boolean;
  consolidatedField: number;

  conditionUpcs: any[];
  participatingProducts: any[];
  isBundle: boolean;
  isLoadedParticipatingProducts = false;
  store: any;
  saleTagImageUrl: string;

  private destroy$ = new Subject<boolean>();
  public unsub: Subscription;
  public isShoppingList: boolean = false;
  public loaded: boolean = false;
  constructor(
    public route: ActivatedRoute,
    public offerService: OfferService,
    public offerProductService: OfferProductService,
    public cStore: CurrentStore,
    public cre: Credential,
    private routeTracker: RouteTrackerService,
    public router: Router,
    private appSettings: AppSettings,
    private ngZone: NgZone
  ) {}

  ngOnInit() {
    this.appSettings
      .getSettingValue('digital_circular_default_sale_tag_image_url')
      .pipe(takeUntil(this.destroy$))
      .subscribe((value) => {
        this.saleTagImageUrl = value;
      });

    this.route.paramMap.pipe(takeUntil(this._destroy$)).subscribe((params) => {
      this.offerCode = params.get('offerCode');
    });

    const firstLoad = this.route.snapshot.queryParamMap.get('transactionId');
    if (firstLoad) {
      this.transactionId = firstLoad;
    } else {
      this.route.queryParamMap.pipe(takeUntil(this._destroy$)).subscribe(async (queryParams) => {
        this.transactionId = queryParams.get('transactionId');
        if (!this.transactionId) return;
        await this.loadData();
      });
    }

    this.routeTracker
      .getRenderType()
      .pipe(takeUntil(this.destroy$))
      .subscribe((value) => {
        this.isShoppingList = value === EnumMagFulfillmentManagementRenderType.ShoppingList;
      });
    this.init();
  }

  ngOnDestroy() {
    this._destroy$.next(true);
    this._destroy$.complete();
    this.unsub?.unsubscribe();
  }

  ionViewDidEnter() {
    window.addEventListener('scrollToTop', this.handleScrollToTop);
  }
  ionViewWillLeave() {
    window.removeEventListener('scrollToTop', this.handleScrollToTop);
  }

  @HostListener('window:couponIsClipped', ['$event'])
  public handleCardClipped(e: CustomEvent) {
    const { isClipped, transactionId } = e.detail;
    if (!isClipped) return;
    this.transactionId = transactionId;
    this.loadData();
  }

  handleScrollToTop = () => {
    this.content.scrollToTop();
  };

  async loadData() {
    this.loaded = false;
    this.offer = await this.fetchOfferData();
    if (!this.offer) {
      this.ngZone.run(() => {
        this.loaded = true;
      });
      console.error('Offer not found');
      return;
    }

    this.updateMagGallery(this.offer?.ImageUrl);
    this.initOfferData();
    this.ngZone.run(() => {
      this.loaded = true;
    });
  }

  async init() {
    this.store = await this.cStore.getStore();
    if (!this.store) {
      console.error('Store not found');
      return;
    }

    await this.loadData();
    // await this.initParticipatingData();
    // get UPCs of Offer - TODO
    const { ParticipatingUpcs, ConditionUpcs, IsBundle } = this.offer || {};
    this.conditionUpcs =
      ParticipatingUpcs?.length > 0
        ? ParticipatingUpcs
        : ConditionUpcs?.length > 0
          ? ConditionUpcs.map((x) => x.Upcs)
          : [];
    this.isBundle = IsBundle;
  }

  initOfferData() {
    const { ExpirationDate, StartDate, EndDate, ConsolidatedField } = this.offer || {};
    this.offerExpirationDate = ExpirationDate ? moment(ExpirationDate).format('MMM DD, YYYY') : '';
    this.startDate = StartDate ? moment(StartDate).format('MMM DD, YYYY') : '';
    this.endDate = EndDate ? moment(EndDate).format('MMM DD, YYYY') : '';
    this.isCoupon = ConsolidatedField === EnumMagOfferType.StoreCoupon;
    this.consolidatedField = ConsolidatedField;
    this.saleTagImageUrl = this.offer?.CouponDisplayType == enumCouponDisplayType?.WeeklyAd && this.saleTagImageUrl;
  }

  async initParticipatingData() {
    const { ParticipatingUpcs, ConditionUpcs, IsBundle } = this.offer || {};

    this.conditionUpcs =
      ParticipatingUpcs?.length > 0
        ? ParticipatingUpcs
        : ConditionUpcs?.length > 0
          ? ConditionUpcs.map((x) => x.Upcs)
          : [];

    if (this.conditionUpcs?.length > 0) {
      const dataSource = await (IsBundle
        ? this.processUpcGroups(this.conditionUpcs)
        : this.fetchDataByUpcs(this.conditionUpcs));
      this.participatingProducts = dataSource?.length > 0 ? dataSource : null;
    }
    this.isBundle = IsBundle;
    this.isLoadedParticipatingProducts = true;
  }

  async processUpcGroups(upcGroups: string[][]) {
    try {
      const promises = upcGroups.map((group) => this.fetchDataByUpcs(group));
      const results = await Promise.all(promises);
      return results;
    } catch (error) {
      console.error('Error processing UPC groups:', error);
      return [];
    }
  }

  async fetchDataByUpcs(upcs: string[]) {
    return await firstValueFrom(
      this.offerProductService.getParticipatingProducts(upcs, this.store?.StoreCode, true, this.cre.currentUser)
    );
  }

  async fetchOfferData() {
    try {
      const offerData = await firstValueFrom(
        this.offerService.getOfferByCode(this.store?.StoreCode, this.offerCode, this.transactionId)
      );
      if (!offerData) return null;
      return offerData;
    } catch (error) {
      console.error('Error fetching offer data:', error);
      return null;
    }
  }

  updateMagGallery(payload: string) {
    if (!payload) return;
    this.magGallery = `<mag-gallery image-string='${payload}'></mag-gallery`;
  }
}
