import { Injectable } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { MagEComCoreApiHttpClient } from '@rsApp/modules/gateway/mag-ecom-core-api.service';
import { catchError, map, of } from 'rxjs';

@Injectable({ providedIn: 'root' })
export class OfferProductService {
  constructor(
    public route: ActivatedRoute,
    public api: MagEComCoreApiHttpClient
  ) {}

  getParticipatingProducts(upcs: string[], storeCode: string, includeOffers: boolean, user: any) {
    const params = {
      upcs,
      storeCode,
      includeOffers,
      customerCode: user && user.ExternalCustomerID,
    };
    return this.api.post('/product/v2.0/api/products/by-upcs', params).pipe(
      map((data: any) => {
        return data.Data;
      }),
      catchError(() => {
        return of([]);
      })
    );
  }
}
