import { NgModule } from '@angular/core';
import { RouterModule, Routes } from '@angular/router';
import { OfferModule } from './offer.module';
import { OfferDetailPageComponent } from './pages/offer-detail/offer-detail';
import { OfferListPageComponent } from './pages/offer-list/offer-list';
import { CouponsListPageComponent } from './pages/coupons-list/coupons-list';
import { RewardsPageComponent } from './pages/rewards/rewards';
import { LoadedSavingPageComponent } from './pages/loaded-savings/loaded-saving';
import { DealsPageComponent } from './pages/deals-page/deals-page';
import { CouponDetailPageComponent } from './pages/coupon-detail/coupon-detail';
import { RewardDetailPageComponent } from './pages/reward-detail/reward-detail';
import { AuthGuardService as AuthGuard } from '@rsApp/modules/auth-v2/guards/auth-guard.service';

const routes: Routes = [
  {
    path: '',
    component: DealsPageComponent,
    children: [
      {
        path: '',
        redirectTo: 'rewards',
        pathMatch: 'full',
      },
      {
        path: 'offers',
        component: OfferListPageComponent,
      },
      {
        path: 'deals',
        component: OfferListPageComponent,
      },
      {
        path: 'rewards',
        component: RewardsPageComponent,
        children: [
          {
            path: ':slug',
            component: RewardsPageComponent,
          },
        ],
        canActivate: [AuthGuard],
      },
      {
        path: 'loaded-savings',
        component: LoadedSavingPageComponent,
        canActivate: [AuthGuard],
      },
      {
        path: 'coupons',
        component: CouponsListPageComponent,
        canActivate: [AuthGuard],
      },
    ],
  },
  {
    path: 'coupons-detail/:couponCode',
    component: CouponDetailPageComponent,
    data: {
      hideTab: true,
    },
  },
  {
    path: 'offer-detail/:offerCode',
    component: OfferDetailPageComponent,
    data: {
      hideTab: true,
    },
  },
  {
    path: 'reward-detail/:offerCode',
    component: RewardDetailPageComponent,
    data: {
      hideTab: true,
    },
  },
];

@NgModule({
  imports: [RouterModule.forChild(routes), OfferModule],
  declarations: [],
})
export class OfferRoutingModule {}
