import { CommonModule } from '@angular/common';
import { HttpHandler } from '@angular/common/http';
import { NgModule } from '@angular/core';
import { ENV } from '@app/env';
import { IonicModule } from '@ionic/angular';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
import { MagEComCoreApiHttpClientFactory } from '@rsApp/modules/gateway/mag-ecom-core-api.service';
import { UtilsModule } from '@rsApp/modules/utils/utils.module';
import { EnvironmentService } from '../../../../environments/environment.service';
import {
  MAG_OFFER_DXP_CORE_API,
  MAG_OFFER_V2_HTTP_CLIENT,
  MAG_REWARD_API,
  MAG_REWARD_HTTP_CLIENT,
} from '../utils/ecom-api-configs';
import { OfferService } from './providers/offer.service';

@NgModule({
  imports: [CommonModule, IonicModule, UtilsModule],
  exports: [],
  declarations: [],
  providers: [
    {
      provide: MAG_OFFER_DXP_CORE_API,
      useValue: ENV.DXPCoreAPI,
    },
    {
      provide: MAG_OFFER_V2_HTTP_CLIENT,
      useFactory: MagEComCoreApiHttpClientFactory,
      deps: [HttpHandler, Credential, MAG_OFFER_DXP_CORE_API, EnvironmentService],
    },
    {
      provide: MAG_REWARD_API,
      useValue: ENV.EComRewardAPIURL,
    },
    {
      provide: MAG_REWARD_HTTP_CLIENT,
      useFactory: MagEComCoreApiHttpClientFactory,
      deps: [HttpHandler, Credential, MAG_REWARD_API, EnvironmentService],
    },
    OfferService,
  ],
})
export class OfferServiceModule {}
