import { Component, NgZone, OnDestroy, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { CurrentStore } from '@rsApp/modules/store/store.module';
import * as moment from 'moment';
import { firstValueFrom, Subject, takeUntil } from 'rxjs';
import { IMagCouponDetail } from '../../model/interface';
import { OfferProductService } from '../../providers/offer-product.service';
import { OfferService } from '../../providers/offer.service';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
import { RouteTrackerService } from '@rsApp/modules/utils/providers/route-tracker.service';

@Component({
  selector: 'coupon-detail',
  templateUrl: './coupon-detail.html',
  styleUrls: ['./coupon-detail.scss'],
})
export class CouponDetailPageComponent implements OnInit, OnDestroy {
  private _destroy$: Subject<boolean> = new Subject();
  coupon: IMagCouponDetail;
  magGallery: string;
  couponCode: string;
  transactionId: string;
  couponExpirationDate: string;
  startDate: string;
  endDate: string;
  isCoupon: boolean;
  consolidatedField: number;

  conditionUpcs: any[];
  participatingProducts: any[];
  isBundle: boolean;
  isLoadedParticipatingProducts = false;
  store: any;
  public isShoppingList: boolean = false;
  public loaded: boolean = false;

  constructor(
    public router: Router,
    public route: ActivatedRoute,
    public offerService: OfferService,
    public offerProductService: OfferProductService,
    public cStore: CurrentStore,
    public cre: Credential,
    private routeTracker: RouteTrackerService,
    private ngZone: NgZone
  ) {}

  async ngOnInit() {
    this.route.paramMap.pipe(takeUntil(this._destroy$)).subscribe((params) => {
      this.couponCode = params.get('couponCode');
    });
    try {
      await this.init();
    } catch (error) {
      console.error(error);
    }
  }

  ngOnDestroy() {
    this._destroy$.next(true);
    this._destroy$.complete();
  }

  // async ionViewWillEnter() {
  //   try {
  //     await this.init();
  //   } catch (error) {
  //     console.error(error);
  //   }
  // }

  async init() {
    this.store = await this.cStore.getStore();
    if (!this.store) {
      console.error('Store not found');
      return;
    }
    this.loaded = false;

    this.coupon = await this.fetchCoupon();
    if (!this.coupon) {
      this.ngZone.run(() => {
        this.loaded = true;
      });
      console.error('Offer not found');
      return;
    }

    this.updateMagGallery(this.coupon?.ImageURL);
    this.initCouponData();
    //TODO : Uncomment and implement this method when needed
    await this.initParticipatingData();
    this.ngZone.run(() => {
      this.loaded = true;
    });
  }

  initCouponData() {
    const { ExpireDate, StartDate, EndDate } = this.coupon || {};
    this.couponExpirationDate = ExpireDate ? moment(ExpireDate).format('MMM DD, YYYY') : '';
    this.startDate = StartDate ? moment(StartDate).format('MMM DD, YYYY') : '';
    this.endDate = EndDate ? moment(EndDate).format('MMM DD, YYYY') : '';
  }

  async initParticipatingData() {
    const { Upcs } = this.coupon || {};
    this.conditionUpcs = Upcs;
    if (this.conditionUpcs?.length > 0) {
      const dataSource = await this.fetchDataByUpcs(this.conditionUpcs);
      this.participatingProducts = dataSource?.length > 0 ? dataSource : null;
    }

    //just for test , will remove when has data
    this.isBundle = false;
    this.isLoadedParticipatingProducts = true;
  }

  async processUpcGroups(upcGroups: string[][]) {
    try {
      const promises = upcGroups.map((group) => this.fetchDataByUpcs(group));
      const results = await Promise.all(promises);
      return results;
    } catch (error) {
      console.error('Error processing UPC groups:', error);
      return [];
    }
  }

  async fetchDataByUpcs(upcs: string[]) {
    return await firstValueFrom(
      this.offerProductService.getParticipatingProducts(upcs, this.store?.StoreCode, true, this.cre.currentUser)
    );
  }

  async fetchCoupon() {
    try {
      const coupon = await firstValueFrom(this.offerService.getCouponByCode(this.couponCode));
      if (!coupon) return null;
      return coupon;
    } catch (error) {
      console.error('Error fetching offer data:', error);
      return null;
    }
  }

  updateMagGallery(payload: string) {
    if (!payload) return;
    this.magGallery = `<mag-gallery image-string='${payload}'></mag-gallery`;
  }
}
